CREATE TABLE scout_companies (id text PRIMARY KEY, name text NOT NULL, active integer NOT NULL DEFAULT 1 CHECK(active IN (0,1)), current_configuration_id text, created_at text NOT NULL, updated_at text NOT NULL);--> statement-breakpoint
CREATE TABLE scout_company_configurations (id text PRIMARY KEY, company_id text NOT NULL REFERENCES scout_companies(id), version integer NOT NULL CHECK(version > 0), fingerprint text NOT NULL, created_at text NOT NULL, UNIQUE(company_id, version), UNIQUE(company_id, fingerprint));--> statement-breakpoint
CREATE TABLE scout_company_configuration_sources (id text PRIMARY KEY, company_configuration_id text NOT NULL REFERENCES scout_company_configurations(id), source_key text NOT NULL, source_type text NOT NULL CHECK(source_type IN ('json','html')), settings_json text NOT NULL CHECK(json_valid(settings_json)), active integer NOT NULL DEFAULT 1 CHECK(active IN (0,1)), UNIQUE(company_configuration_id, source_key));--> statement-breakpoint
CREATE TABLE scout_runs (id text PRIMARY KEY, status text NOT NULL CHECK(status IN ('queued','running','completed','partial','failed')), run_type text NOT NULL DEFAULT 'full' CHECK(run_type = 'full'), batch_size integer NOT NULL CHECK(batch_size > 0), concurrency integer NOT NULL CHECK(concurrency > 0), created_at text NOT NULL, started_at text, completed_at text, company_count integer NOT NULL DEFAULT 0, succeeded_count integer NOT NULL DEFAULT 0, failed_count integer NOT NULL DEFAULT 0);--> statement-breakpoint
CREATE UNIQUE INDEX scout_runs_one_active_full_idx ON scout_runs(run_type) WHERE status IN ('queued','running');--> statement-breakpoint
CREATE TABLE scout_run_companies (id text PRIMARY KEY, run_id text NOT NULL REFERENCES scout_runs(id), company_id text NOT NULL REFERENCES scout_companies(id), company_configuration_id text NOT NULL REFERENCES scout_company_configurations(id), status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','succeeded','partial','failed')), started_at text, completed_at text, failure_code text CHECK(failure_code IS NULL OR length(failure_code) <= 100), failure_message text CHECK(failure_message IS NULL OR length(failure_message) <= 500), UNIQUE(run_id, company_id));--> statement-breakpoint
CREATE TABLE scout_run_sources (id text PRIMARY KEY, run_company_id text NOT NULL REFERENCES scout_run_companies(id), configuration_source_id text NOT NULL REFERENCES scout_company_configuration_sources(id), status text NOT NULL CHECK(status IN ('succeeded_with_results','succeeded_empty_verified','suspicious_empty','partial','failed')), candidate_count integer NOT NULL DEFAULT 0, accepted_count integer NOT NULL DEFAULT 0, rejected_count integer NOT NULL DEFAULT 0, UNIQUE(run_company_id, configuration_source_id));--> statement-breakpoint
CREATE TABLE scout_source_attempts (id text PRIMARY KEY, run_source_id text NOT NULL REFERENCES scout_run_sources(id), attempt_number integer NOT NULL, adapter text NOT NULL, stage text NOT NULL, request_count integer NOT NULL, response_count integer NOT NULL, candidate_count integer NOT NULL, accepted_count integer NOT NULL, rejected_count integer NOT NULL, validation_status text NOT NULL, started_at text NOT NULL, completed_at text NOT NULL, failure_code text CHECK(failure_code IS NULL OR length(failure_code) <= 100), failure_message text CHECK(failure_message IS NULL OR length(failure_message) <= 500), UNIQUE(run_source_id, attempt_number));--> statement-breakpoint
CREATE TABLE scout_attempt_diagnostics (id text PRIMARY KEY, source_attempt_id text NOT NULL REFERENCES scout_source_attempts(id), code text NOT NULL, category text NOT NULL, count integer NOT NULL, message text NOT NULL CHECK(length(message) <= 500));--> statement-breakpoint
CREATE TABLE scout_run_outbox (id text PRIMARY KEY, run_company_id text NOT NULL UNIQUE REFERENCES scout_run_companies(id), queue_job_id text NOT NULL UNIQUE, dispatch_status text NOT NULL DEFAULT 'pending' CHECK(dispatch_status IN ('pending','dispatched')), created_at text NOT NULL, dispatched_at text);--> statement-breakpoint
CREATE TABLE scout_positions (id text PRIMARY KEY, company_id text NOT NULL REFERENCES scout_companies(id), source_key text NOT NULL, identity_kind text NOT NULL CHECK(identity_kind IN ('external_id','canonical_url','fingerprint')), identity_value text NOT NULL, external_id text, canonical_url text NOT NULL, title text NOT NULL, location text, first_seen_at text NOT NULL, last_seen_at text NOT NULL, UNIQUE(company_id, source_key, identity_kind, identity_value));--> statement-breakpoint
CREATE TABLE scout_description_artifacts (id text PRIMARY KEY, file_path text NOT NULL UNIQUE CHECK(instr(file_path, '..') = 0 AND substr(file_path,1,1) <> '/'), content_hash text NOT NULL, media_type text NOT NULL CHECK(media_type IN ('text/plain','text/markdown')), byte_count integer NOT NULL CHECK(byte_count >= 0), provenance_json text NOT NULL CHECK(json_valid(provenance_json)), created_at text NOT NULL, UNIQUE(content_hash, media_type));--> statement-breakpoint
CREATE TABLE scout_position_observations (id text PRIMARY KEY, run_source_id text NOT NULL REFERENCES scout_run_sources(id), position_id text NOT NULL REFERENCES scout_positions(id), description_artifact_id text REFERENCES scout_description_artifacts(id), title text NOT NULL, canonical_url text NOT NULL, location text, provenance_json text NOT NULL CHECK(json_valid(provenance_json)), observed_at text NOT NULL, UNIQUE(run_source_id, position_id));--> statement-breakpoint
CREATE INDEX scout_run_companies_run_idx ON scout_run_companies(run_id, status);--> statement-breakpoint
CREATE INDEX scout_observations_run_source_idx ON scout_position_observations(run_source_id, observed_at, id);
